1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUM_RATES: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const CURSE_SURCHARGE_RATE = 0.5;
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
57	const LOYALTY_YEARS_THRESHOLD = 2;
58	const LOYALTY_DISCOUNT_RATE = 0.2;
59	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
60	const COMPONENT_BLOCK_SIZE = 3;
61	const COMPONENT_BLOCK_PREMIUM = 60;
62	
63	const INSURANCE_VALUES: Record<string, number> = {
64	  sword: 1000,
65	  amulet: 600,
66	  staff: 800,
67	  potion: 400,
68	  rune: 250,
69	  moonstone: 250,
70	};
71	
72	const DEDUCTIBLE_PER_DAMAGE = 100;
73	const CAP_MULTIPLIER = 2;
74	const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
75	const HALF_REIMBURSEMENT_RATE = 0.5;
76	const FULL_REIMBURSEMENT_RATE = 1;
77	
78	const countByType = (items: Item[]): Map<string, number> =>
79	  items.reduce(
80	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
81	    new Map<string, number>(),
82	  );
83	
84	const basePremiumForGroup = (type: string, itemCount: number): number =>
85	  itemCount === COMPONENT_BLOCK_SIZE
86	    ? COMPONENT_BLOCK_PREMIUM
87	    : itemCount * BASE_PREMIUM_RATES[type];
88	
89	// The policy base premium: the sum of all item base premiums, EXCLUDING
90	// item-specific surcharges. Policy-wide modifiers are percentages of this.
91	const policyBasePremium = (items: Item[]): number =>
92	  [...countByType(items)].reduce(
93	    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
94	    0,
95	  );
96	
97	const itemSurchargeRate = (item: Item): number =>
98	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
99	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
100	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
101	    : 0);
102	
103	const sumItemSurcharges = (items: Item[]): number =>
104	  items.reduce(
105	    (sum, item) => sum + BASE_PREMIUM_RATES[item.type] * itemSurchargeRate(item),
106	    0,
107	  );
108	
109	// Premiums round in the MHPCO's favor, i.e. up.
110	const roundPremiumInMHPCOsFavor = (premium: number): number =>
111	  Math.ceil(premium);
112	
113	// What the office knows about the customer at the moment a quote is drawn up.
114	// Policy-wide modifiers are decided entirely by this context.
115	interface QuoteContext {
116	  customer: Customer;
117	  precedingQuoteCount: number;
118	}
119	
120	// Each policy-wide modifier is a signed percentage of the policy base premium:
121	// surcharges positive, discounts negative.
122	const policyWideModifierRates = ({
123	  customer,
124	  precedingQuoteCount,
125	}: QuoteContext): number[] => [
126	  FIRST_INSURANCE_SURCHARGE_RATE,
127	  ...(customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
128	    ? [-LOYALTY_DISCOUNT_RATE]
129	    : []),
130	  ...(precedingQuoteCount > 0 ? [-FOLLOW_UP_CONTRACT_DISCOUNT_RATE] : []),
131	];
132	
133	// Each rate is multiplied out against the base premium SEPARATELY and then
134	// summed. Summing the rates first and doing a single multiply is algebraically
135	// equal but not equal in floating point — 100 * (1 + 0.1) is 110.00000000000001
136	// — and rounding up turns that into a spurious extra gold piece.
137	const sumPolicyWideModifiers = (
138	  basePremium: number,
139	  context: QuoteContext,
140	): number =>
141	  policyWideModifierRates(context).reduce(
142	    (sum, rate) => sum + basePremium * rate,
143	    0,
144	  );
145	
146	const quote = (items: Item[], context: QuoteContext): StepResult => {
147	  const basePremium = policyBasePremium(items);
148	
149	  return {
150	    premium: roundPremiumInMHPCOsFavor(
151	      basePremium +
152	        sumItemSurcharges(items) +
153	        sumPolicyWideModifiers(basePremium, context) +
154	        PROCESSING_FEE,
155	    ),
156	  };
157	};
158	
159	const policyInsuranceSum = (items: Item[]): number =>
160	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
161	
162	// How much of a damage the office reimburses, before the deductible.
163	const reimbursementRate = (item: Item): number =>
164	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT
165	    ? HALF_REIMBURSEMENT_RATE
166	    : FULL_REIMBURSEMENT_RATE;
167	
168	const payoutForDamage = (damage: Damage, item: Item): number =>
169	  Math.max(
170	    0,
171	    damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE,
172	  );
173	
174	const claim = (step: ClaimStep, policyItems: Item[]): StepResult => {
175	  const payout = step.incident.damages.reduce((sum, damage) => {
176	    const item = policyItems.find(({ type }) => type === damage.itemType)!;
177	
178	    return sum + payoutForDamage(damage, item);
179	  }, 0);
180	  const cap = policyInsuranceSum(policyItems) * CAP_MULTIPLIER;
181	
182	  return { payout, remainingCap: cap - payout };
183	};
184	
185	// Policies the office has written so far, keyed by the step index of the quote
186	// that created them — that index is how a later claim step refers to a policy.
187	// The number of entries is also exactly the number of preceding quotes, which
188	// is what decides the follow-up contract discount; deriving it here keeps the
189	// two facts from drifting apart.
190	type PoliciesSoFar = Map<number, Item[]>;
191	
192	export const runScenario = (scenario: Scenario): ScenarioResult => {
193	  const policies: PoliciesSoFar = new Map();
194	
195	  const results = scenario.steps.map((step, stepIndex) => {
196	    if (step.op === "claim") {
197	      return claim(step, policies.get(step.policy)!);
198	    }
199	
200	    const result = quote(step.items, {
201	      customer: scenario.customer,
202	      precedingQuoteCount: policies.size,
203	    });
204	    policies.set(stepIndex, step.items);
205	
206	    return result;
207	  });
208	
209	  return { results };
210	};
